def transform(grid):
    if len(grid) > 1 and len(set(grid[len(grid)//2])) == 1:
        # Horizontal separator: use the panel above it.
        sep = next(i for i, row in enumerate(grid) if len(set(row)) == 1)
        panel = grid[:sep]
    else:
        # Vertical separator: use the panel to its left.
        sep = next(c for c in range(len(grid[0]))
                   if all(row[c] == grid[0][c] for row in grid))
        panel = [row[:sep] for row in grid]

    marks = [v for row in panel for v in row if v not in (0, 7)]
    color = marks[0] if marks else 0
    return [[3 if v == color else color for v in row] for row in panel]
