def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_row = next((r for r, row in enumerate(grid)
                    if len(set(row)) == 1), None)
    if sep_row is not None:
        top, bottom = grid[:sep_row], grid[sep_row + 1:]
        bg = next(v for v in top[0] if v != 0)
        out = [[bg] * w for _ in top]
        for r in range(len(top)):
            for c in range(w):
                if top[r][c] != bg and bottom[r][c] != bg:
                    out[r][c] = 3
        return out

    sep_col = next(c for c in range(w)
                   if len({grid[r][c] for r in range(h)}) == 1)
    left = [row[:sep_col] for row in grid]
    right = [row[sep_col + 1:] for row in grid]
    bg = next(v for row in right for v in row if v not in (0, 6))
    out = [[bg] * len(left[0]) for _ in range(h)]
    for r in range(h):
        for c in range(len(left[0])):
            if left[r][c] not in (0, bg, 6) and right[r][c] == bg + 1:
                out[r][c] = 3
    return out
